content:
:root {
  --color-bg: #f8fafc;
  --color-surface: #ffffff;
  --color-border: #e2e8f0;
  --color-border-hover: #cbd5e1;
  --color-text-primary: #0f172a;
  --color-text-secondary: #64748b;
  --color-text-muted: #94a3b8;

  --color-primary: #3b82f6;
  --color-primary-light: #eff6ff;
  --color-primary-dark: #1d4ed8;

  --color-success: #10b981;
  --color-success-bg: #ecfdf5;
  --color-success-text: #047857;

  --color-danger: #ef4444;
  --color-danger-bg: #fef2f2;
  --color-danger-text: #b91c1c;

  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.07), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.04);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  margin: 0;
  font-family: var(--font-family);
  background-color: var(--color-bg);
  color: var(--color-text-primary);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

/* ダッシュボードコンテナ */
.dashboard-container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 24px 20px 48px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

/* ヘッダー */
.dashboard-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
  padding-bottom: 8px;
}

.header-title-group {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.header-title {
  font-size: 1.625rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--color-text-primary);
}

.header-subtitle {
  font-size: 0.875rem;
  color: var(--color-text-secondary);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

/* 期間フィルターボタン群 */
.filter-group {
  display: inline-flex;
  background-color: #e2e8f0;
  padding: 4px;
  border-radius: var(--radius-md);
  gap: 4px;
}

.filter-btn {
  padding: 6px 14px;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-text-secondary);
  border-radius: var(--radius-sm);
  transition: all 0.2s ease;
}

.filter-btn:hover {
  color: var(--color-text-primary);
}

.filter-btn-active {
  background-color: var(--color-surface);
  color: var(--color-text-primary);
  box-shadow: var(--shadow-sm);
  font-weight: 600;
}

/* KPIグリッド */
.kpi-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 16px;
}

/* KPIカード */
.kpi-card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  cursor: pointer;
  transition: transform 0.15s ease, box-shadow 0.15s ease, border-color 0.15s ease;
  position: relative;
  box-shadow: var(--shadow-sm);
}

.kpi-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
  border-color: var(--color-border-hover);
}

.kpi-card-active {
  border-color: var(--color-primary);
  background-color: #ffffff;
  box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.2), var(--shadow-md);
}

.kpi-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.kpi-title {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-text-secondary);
}

/* 増減率バッジ */
.kpi-badge {
  display: inline-flex;
  align-items: center;
  font-size: 0.75rem;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 9999px;
  line-height: 1.3;
}

.kpi-badge-positive {
  background-color: var(--color-success-bg);
  color: var(--color-success-text);
}

.kpi-badge-negative {
  background-color: var(--color-danger-bg);
  color: var(--color-danger-text);
}

.kpi-value-row {
  display: flex;
  align-items: baseline;
  gap: 6px;
}

.kpi-value {
  font-size: 2rem;
  font-weight: 700;
  line-height: 1.1;
  color: var(--color-text-primary);
  font-feature-settings: "tnum";
  font-variant-numeric: tabular-nums;
}

.kpi-unit {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-text-secondary);
}

.kpi-subtext {
  font-size: 0.75rem;
  color: var(--color-text-muted);
}

/* グラフセクション */
.charts-section {
  display: flex;
  flex-direction: column;
}

.chart-card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.chart-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
}

.chart-title {
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--color-text-primary);
}

.chart-controls {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.chart-toggle-btn {
  padding: 6px 12px;
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--color-text-secondary);
  background-color: #f1f5f9;
  border-radius: var(--radius-sm);
  transition: all 0.2s ease;
}

.chart-toggle-btn:hover {
  background-color: #e2e8f0;
  color: var(--color-text-primary);
}

.chart-toggle-btn-active {
  background-color: var(--color-primary);
  color: #ffffff;
}

.chart-toggle-btn-active:hover {
  background-color: var(--color-primary-dark);
}

.chart-wrapper {
  width: 100%;
  height: 380px;
  position: relative;
}

/* グラフカスタムツールチップ */
.custom-tooltip {
  background-color: rgba(15, 23, 42, 0.92);
  color: #ffffff;
  padding: 10px 14px;
  border-radius: var(--radius-sm);
  box-shadow: var(--shadow-lg);
  font-size: 0.8125rem;
  backdrop-filter: blur(4px);
  pointer-events: none;
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 140px;
}

.tooltip-label {
  font-weight: 600;
  border-bottom: 1px solid rgba(255, 255, 255, 0.15);
  padding-bottom: 4px;
  color: #f8fafc;
}

.tooltip-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.tooltip-color-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  display: inline-block;
  margin-right: 6px;
}

.tooltip-name {
  color: #cbd5e1;
  display: flex;
  align-items: center;
}

.tooltip-val {
  font-weight: 600;
  font-feature-settings: "tnum";
  font-variant-numeric: tabular-nums;
  color: #ffffff;
}

/* テーブルセクション */
.table-section {
  display: flex;
  flex-direction: column;
}

.table-card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  overflow: hidden;
}

.table-header {
  padding: 20px 24px 16px;
  border-bottom: 1px solid var(--color-border);
}

.table-container {
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.data-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 0.875rem;
}

.data-table th {
  background-color: #f8fafc;
  color: var(--color-text-secondary);
  font-weight: 600;
  padding: 12px 20px;
  border-bottom: 1px solid var(--color-border);
  white-space: nowrap;
}

.data-table td {
  padding: 14px 20px;
  border-bottom: 1px solid var(--color-border);
  color: var(--color-text-primary);
  white-space: nowrap;
}

.data-table tbody tr:last-child td {
  border-bottom: none;
}

.data-table tbody tr:hover {
  background-color: #f8fafc;
}

.table-num {
  text-align: right;
  font-feature-settings: "tnum";
  font-variant-numeric: tabular-nums;
}

th.table-num {
  text-align: right;
}

/* 増減タグ */
.tag-up,
.tag-down {
  display: inline-flex;
  align-items: center;
  font-size: 0.75rem;
  font-weight: 600;
  padding: 2px 6px;
  border-radius: 4px;
}

.tag-up {
  color: var(--color-success-text);
  background-color: var(--color-success-bg);
}

.tag-down {
  color: var(--color-danger-text);
  background-color: var(--color-danger-bg);
}

/* レスポンシブ対応 */
@media (max-width: 768px) {
  .dashboard-container {
    padding: 16px 12px 32px;
    gap: 16px;
  }

  .dashboard-header {
    flex-direction: column;
    align-items: flex-start;
  }

  .header-actions {
    width: 100%;
    justify-content: flex-start;
  }

  .filter-group {
    width: 100%;
  }

  .filter-btn {
    flex: 1;
    text-align: center;
  }

  .kpi-value {
    font-size: 1.75rem;
  }

  .chart-card {
    padding: 16px 12px;
  }

  .chart-wrapper {
    height: 300px;
  }

  .data-table th,
  .data-table td {
    padding: 10px 12px;
  }
}

export interface MonthlySalesRecord {
  month: string;
  revenue: number;
  customers: number;
  averageSpend: number;
  targetRevenue: number;
}

export interface KpiMetric {
  id: string;
  title: string;
  value: number;
  formattedValue: string;
  changeRate: number;
  unit: string;
  isPositive: boolean;
}

export type PeriodFilter = '6months' | '12months';

export interface KpiCardProps {
  metric: KpiMetric;
  isSelected: boolean;
  onSelect: (id: string) => void;
}

export interface DashboardChartsProps {
  data: MonthlySalesRecord[];
  activeMetricId: string;
}

import { MonthlySalesRecord, KpiMetric, PeriodFilter } from './types';

export const ANNUAL_SALES_DATA: MonthlySalesRecord[] = [
  { month: '1月', revenue: 3820000, customers: 1240, averageSpend: 3080, targetRevenue: 3600000 },
  { month: '2月', revenue: 3450000, customers: 1110, averageSpend: 3108, targetRevenue: 3500000 },
