  { month: '8月', revenue: 5310000, customers: 1560, averageSpend: 3403, targetRevenue: 5000000 },
  { month: '9月', revenue: 4720000, customers: 1400, averageSpend: 3371, targetRevenue: 4600000 },
  { month: '10月', revenue: 5120000, customers: 1480, averageSpend: 3459, targetRevenue: 4900000 },
  { month: '11月', revenue: 5440000, customers: 1530, averageSpend: 3555, targetRevenue: 5200000 },
  { month: '12月', revenue: 6280000, customers: 1690, averageSpend: 3715, targetRevenue: 5800000 },
];

export const calculateGrowthRate = (current: number, previous: number): number => {
  if (!previous || previous === 0) return 0;
  const rate = ((current - previous) / previous) * 100;
  return Math.round(rate * 10) / 10;
};

export const getFilteredSalesData = (period: PeriodFilter): MonthlySalesRecord[] => {
  if (period === '6months') {
    return ANNUAL_SALES_DATA.slice(-6);
  }
  return ANNUAL_SALES_DATA;
};

export const computeKpiMetrics = (data: MonthlySalesRecord[]): KpiMetric[] => {
  if (data.length === 0) {
    return [];
  }

  const latest = data[data.length - 1];
  const previous = data.length > 1 ? data[data.length - 2] : latest;

  const totalRevenue = data.reduce((acc, cur) => acc + cur.revenue, 0);
  const totalCustomers = data.reduce((acc, cur) => acc + cur.customers, 0);
  const overallAverageSpend = totalCustomers > 0 ? Math.round(totalRevenue / totalCustomers) : 0;

  const revenueGrowth = calculateGrowthRate(latest.revenue, previous.revenue);
  const customersGrowth = calculateGrowthRate(latest.customers, previous.customers);
  const spendGrowth = calculateGrowthRate(latest.averageSpend, previous.averageSpend);

  return [
    {
      id: 'revenue',
      title: '当月売上実績',
      value: latest.revenue,
      formattedValue: latest.revenue.toLocaleString(),
      changeRate: revenueGrowth,
      unit: '円',
      isPositive: revenueGrowth >= 0,
    },
    {
      id: 'customers',
      title: '当月来店客数',
      value: latest.customers,
      formattedValue: latest.customers.toLocaleString(),
      changeRate: customersGrowth,
      unit: '人',
      isPositive: customersGrowth >= 0,
    },
    {
      id: 'averageSpend',
      title: '当月客単価',
      value: latest.averageSpend,
      formattedValue: latest.averageSpend.toLocaleString(),
      changeRate: spendGrowth,
      unit: '円',
      isPositive: spendGrowth >= 0,
    },
  ];
};

import { KpiCardProps } from '../types';

const KpiCard = ({ metric, isSelected = false, onSelect }: KpiCardProps) => {
  const handleClick = () => {
    onSelect?.(metric.id);
  };

  const badgeClass = metric.isPositive
    ? 'kpi-badge kpi-badge-positive'
    : 'kpi-badge kpi-badge-negative';

  const cardClass = isSelected
    ? 'kpi-card kpi-card-active'
    : 'kpi-card';

  const formattedRate = metric.changeRate > 0
    ? `+${metric.changeRate}%`
    : `${metric.changeRate}%`;

  return (
    <div
      className={cardClass}
      onClick={handleClick}
      role="button"
      tabIndex={0}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          handleClick();
        }
      }}
    >
      <div className="kpi-header">
        <span className="kpi-title">{metric.title}</span>
        <span className={badgeClass}>{formattedRate}</span>
      </div>

      <div className="kpi-value-row">
        <span className="kpi-value">{metric.formattedValue}</span>
        <span className="kpi-unit">{metric.unit}</span>
      </div>

      <div className="kpi-subtext">前月比推移 (クリックでグラフ強調)</div>
    </div>
  );
};

export default KpiCard;

import { useState } from 'react';
import {
  ResponsiveContainer,
  ComposedChart,
  Bar,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
} from 'recharts';
import { DashboardChartsProps } from '../types';

interface CustomTooltipProps {
  active?: boolean;
  payload?: Array<{
    name: string;
    value: number;
    color: string;
    dataKey: string;
  }>;
  label?: string;
}

const CustomTooltip = ({ active, payload, label }: CustomTooltipProps) => {
  if (active && payload && payload.length) {
    return (
      <div className="custom-tooltip">
        <div className="tooltip-label">{label}実績詳細</div>
        {payload.map((entry, index) => {
          let formattedVal = `${entry.value?.toLocaleString()}`;
          if (entry.dataKey === 'revenue' || entry.dataKey === 'targetRevenue' || entry.dataKey === 'averageSpend') {
            formattedVal = `${formattedVal} 円`;
          } else if (entry.dataKey === 'customers') {
            formattedVal = `${formattedVal} 人`;
          }

          return (
            <div key={`tooltip-${index}`} className="tooltip-row">
              <span className="tooltip-name">
                <span
                  className="tooltip-color-dot"
                  style={{ backgroundColor: entry.color }}
                />
                {entry.name}
              </span>
              <span className="tooltip-val">{formattedVal}</span>
            </div>
          );
        })}
      </div>
    );
  }
  return null;
};

const DashboardCharts = ({ data = [], activeMetricId = 'revenue' }: DashboardChartsProps) => {
  const [showTarget, setShowTarget] = useState<boolean>(true);

  const toggleTarget = () => {
    setShowTarget((prev) => !prev);
  };

  const getMetricTitle = () => {
    switch (activeMetricId) {
      case 'customers':
        return '来店客数と客単価の推移';
      case 'averageSpend':
        return '平均客単価と売上の推移';
      case 'revenue':
      default:
        return '売上実績と月次目標比較';
    }
  };

  const formatRevenueYAxis = (val: number) => {
    return `${(val / 10000).toFixed(0)}万`;
  };

  const formatCustomersYAxis = (val: number) => {
    return `${val}人`;
  };

  const formatSpendYAxis = (val: number) => {
    return `¥${val.toLocaleString()}`;
  };

  return (
    <section className="charts-section">
      <div className="chart-card">
        <div className="chart-header">
          <h2 className="chart-title">{getMetricTitle()}</h2>
          <div className="chart-controls">
            <button
              type="button"
              className={showTarget ? 'chart-toggle-btn chart-toggle-btn-active' : 'chart-toggle-btn'}
              onClick={toggleTarget}
            >
              目標ライン表示: {showTarget ? 'ON' : 'OFF'}
            </button>
          </div>
        </div>

        <div className="chart-wrapper">
          <ResponsiveContainer width="100%" height="100%">
            {activeMetricId === 'customers' ? (
              <ComposedChart data={data} margin={{ top: 12, right: 16, bottom: 8, left: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" vertical={false} />
                <XAxis dataKey="month" stroke="#64748b" tickLine={false} />
                <YAxis
                  yAxisId="left"
                  stroke="#64748b"
                  tickLine={false}
                  tickFormatter={formatCustomersYAxis}
                />
                <YAxis
                  yAxisId="right"
                  orientation="right"
                  stroke="#64748b"
                  tickLine={false}
                  tickFormatter={formatSpendYAxis}
                />
                <Tooltip content={<CustomTooltip />} />
                <Legend verticalAlign="top" height={36} />
                <Bar
                  yAxisId="left"
                  dataKey="customers"
                  name="来店客数"
                  fill="#3b82f6"
                  radius={[4, 4, 0, 0]}
                  maxBarSize={48}
                />
                <Line
                  yAxisId="right"
                  type="monotone"
                  dataKey="averageSpend"
                  name="平均客単価"
                  stroke="#10b981"
                  strokeWidth={2.5}
                  dot={{ r: 4, fill: '#10b981' }}
                />
              </ComposedChart>
            ) : activeMetricId === 'averageSpend' ? (
              <ComposedChart data={data} margin={{ top: 12, right: 16, bottom: 8, left: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" vertical={false} />
                <XAxis dataKey="month" stroke="#64748b" tickLine={false} />
                <YAxis
                  yAxisId="left"
                  stroke="#64748b"
                  tickLine={false}
                  tickFormatter={formatSpendYAxis}
                />
                <YAxis
                  yAxisId="right"
                  orientation="right"
                  stroke="#64748b"
                  tickLine={false}
                  tickFormatter={formatRevenueYAxis}
                />
                <Tooltip content={<CustomTooltip />} />
                <Legend verticalAlign="top" height={36} />
                <Bar
                  yAxisId="left"
                  dataKey="averageSpend"
                  name="平均客単価"
                  fill="#10b981"
                  radius={[4, 4, 0, 0]}
                  maxBarSize={48}
                />
                <Line
                  yAxisId="right"
                  type="monotone"
                  dataKey="revenue"
                  name="売上実績"
                  stroke="#3b82f6"
                  strokeWidth={2.5}
                  dot={{ r: 4, fill: '#3b82f6' }}
                />
              </ComposedChart>
            ) : (
              <ComposedChart data={data} margin={{ top: 12, right: 16, bottom: 8, left: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" vertical={false} />
                <XAxis dataKey="month" stroke="#64748b" tickLine={false} />
                <YAxis
                  yAxisId="left"
                  stroke="#64748b"
                  tickLine={false}
                  tickFormatter={formatRevenueYAxis}
                />
                <Tooltip content={<CustomTooltip />} />
                <Legend verticalAlign="top" height={36} />
                <Bar
                  yAxisId="left"
                  dataKey="revenue"
                  name="売上実績"
                  fill="#3b82f6"
                  radius={[4, 4, 0, 0]}
                  maxBarSize={48}
                />
                {showTarget && (
                  <Line
                    yAxisId="left"
                    type="monotone"
                    dataKey="targetRevenue"
                    name="目標売上"
                    stroke="#ef4444"
                    strokeWidth={2}
                    strokeDasharray="4 4"
                    dot={{ r: 3, fill: '#ef4444' }}
                  />
                )}
              </ComposedChart>
            )}
          </ResponsiveContainer>
        </div>
      </div>
    </section>
  );
};

export default DashboardCharts;

import { useState, useMemo } from 'react';
import { PeriodFilter } from './types';
import { getFilteredSalesData, computeKpiMetrics, calculateGrowthRate } from './data';
import KpiCard from './components/KpiCard';
import DashboardCharts from './components/DashboardCharts';

const App = () => {
  const [period, setPeriod] = useState<PeriodFilter>('12months');
  const [activeMetricId, setActiveMetricId] = useState<string>('revenue');

  const filteredData = useMemo(() => {
    return getFilteredSalesData(period);
  }, [period]);

  const kpiMetrics = useMemo(() => {
    return computeKpiMetrics(filteredData);
  }, [filteredData]);

  const handlePeriodChange = (newPeriod: PeriodFilter) => {
    setPeriod(newPeriod);
  };

  const handleMetricSelect = (metricId: string) => {
    setActiveMetricId(metricId);
  };

  return (
    <div className="dashboard-container">
      <header className="dashboard-header">
        <div className="header-title-group">
          <h1 className="header-title">売上分析ダッシュボード</h1>
          <p className="header-subtitle">
            主要KPI（売上・客数・客単価）の進捗と月次推移のモニタリング
          </p>
        </div>

        <div className="header-actions">
          <div className="filter-group">
            <button
              type="button"
              className={period === '6months' ? 'filter-btn filter-btn-active' : 'filter-btn'}
              onClick={() => handlePeriodChange('6months')}
            >
              直近6ヶ月
            </button>
            <button
              type="button"
              className={period === '12months' ? 'filter-btn filter-btn-active' : 'filter-btn'}
              onClick={() => handlePeriodChange('12months')}
            >
              通期（12ヶ月）
            </button>
          </div>
        </div>
      </header>

      <section className="kpi-grid">
        {kpiMetrics.map((metric) => (
          <KpiCard
            key={metric.id}
            metric={metric}
            isSelected={activeMetricId === metric.id}
            onSelect={handleMetricSelect}
          />
        ))}
      </section>

      <DashboardCharts
        data={filteredData}
        activeMetricId={activeMetricId}
      />

      <section className="table-section">
        <div className="table-card">
          <div className="table-header">
            <h2 className="chart-title">月別実績詳細</h2>
          </div>

          <div className="table-container">
            <table className="data-table">
              <thead>
                <tr>
                  <th>月度</th>
                  <th className="table-num">売上実績 (円)</th>
                  <th className="table-num">目標売上 (円)</th>
                  <th className="table-num">達成率</th>
                  <th className="table-num">前月比 (売上)</th>
                  <th className="table-num">来店客数 (人)</th>
                  <th className="table-num">平均客単価 (円)</th>
                </tr>
              </thead>
              <tbody>
                {filteredData.map((record, index) => {
                  const achievementRate = record.targetRevenue > 0
                    ? Math.round((record.revenue / record.targetRevenue) * 1000) / 10
                    : 100;

                  const previousRecord = index > 0 ? filteredData[index - 1] : null;
                  const growthRate = previousRecord
                    ? calculateGrowthRate(record.revenue, previousRecord.revenue)
                    : null;

                  return (
                    <tr key={record.month}>
                      <td>{record.month}</td>
                      <td className="table-num">¥{record.revenue.toLocaleString()}</td>
                      <td className="table-num">¥{record.targetRevenue.toLocaleString()}</td>
                      <td className="table-num">
                        {achievementRate >= 100 ? (
                          <span className="tag-up">{achievementRate}%</span>
                        ) : (
                          <span className="tag-down">{achievementRate}%</span>
                        )}
                      </td>
                      <td className="table-num">
                        {growthRate !== null ? (
                          growthRate >= 0 ? (
                            <span className="tag-up">+{growthRate}%</span>
                          ) : (
                            <span className="tag-down">{growthRate}%</span>
                          )
                        ) : (
                          <span style={{ color: 'var(--color-text-muted)' }}>-</span>
                        )}
                      </td>
                      <td className="table-num">{record.customers.toLocaleString()} 人</td>
                      <td className="table-num">¥{record.averageSpend.toLocaleString()}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      </section>
    </div>
  );
};

export default App;
